self.KB_CONTENT["card:779735"]={"id":"card:779735","ty":"card","sourceId":"779735","title":"『產品WIP狀況表』的作業重點有哪些？","ver":"GP4以上","topic":"狀況表","keywords":["狀況表","產品","產出"],"y":"explain","answer":"■作業重點1.前端可彈性選擇是否列印等級資料、是否考慮標準產出率。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
