self.KB_CONTENT["card:752211"]={"id":"card:752211","ty":"card","sourceId":"752211","title":"『密碼參數設定作業』的作業目的為何？","ver":"iGP","topic":"控管","keywords":["控管","鎖定"],"y":"explain","answer":"於此作業設定要列入通知密碼需更新之條件，是間隔多久未更新密碼才須列入；另外可選擇是否控管密碼長度、密碼複雜性及錯誤次數鎖定。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
